def solve(grid):
    import copy
    from collections import Counter

    H = len(grid)
    W = len(grid[0])

    flat = [grid[r][c] for r in range(H) for c in range(W)]
    bg = Counter(flat).most_common(1)[0][0]

    # Find 4 on border to determine shadow direction
    border_4 = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 4 and (r == 0 or r == H-1 or c == 0 or c == W-1):
                border_4 = (r, c)
                break
        if border_4:
            break

    r4, c4 = border_4
    dr, dc = 0, 0
    if r4 == 0: dr = 1
    elif r4 == H-1: dr = -1
    if c4 == 0: dc = 1
    elif c4 == W-1: dc = -1

    result = copy.deepcopy(grid)

    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and grid[r][c] != 4:
                nr, nc = r + dr, c + dc
                while 0 <= nr < H and 0 <= nc < W:
                    if grid[nr][nc] == bg:
                        result[nr][nc] = 0
                    nr += dr
                    nc += dc

    return result
